<script setup>
import { computed, onMounted, ref } from 'vue'
import { getSessions, getSessionReport, archiveSession } from '../api/client'

const sessions = ref([]); const selected = ref(null); const report = ref(null); const loading = ref(true); const reportLoading = ref(false); const archiving = ref(false); const refreshing = ref(false); const errorMessage = ref(''); const mode = ref('classroom'); const page = ref(1); const pageSize = 5
const visibleSessions = computed(() => sessions.value.filter(item => mode.value === 'classroom' ? item.session_type === 'classroom' && item.status === 'closed' : item.session_type === 'homework'))
const pageCount = computed(() => Math.max(1, Math.ceil(visibleSessions.value.length / pageSize)))
const pageSessions = computed(() => visibleSessions.value.slice((page.value - 1) * pageSize, page.value * pageSize))
const isHomework = computed(() => report.value?.session?.session_type === 'homework')
function formatDate(value) { return value ? new Intl.DateTimeFormat('zh-HK', { dateStyle: 'medium', timeStyle: 'short' }).format(new Date(value)) : '未记录时间' }
function accuracyClass(value) { return value >= 80 ? 'accuracy-good' : value >= 50 ? 'accuracy-medium' : 'accuracy-low' }
function sessionTime(item) { return mode.value === 'classroom' ? `结束时间：${formatDate(item.closed_at)}` : `建立时间：${formatDate(item.created_at)}` }
async function openReport(session) { reportLoading.value = true; errorMessage.value = ''; selected.value = session; report.value = null; try { report.value = await getSessionReport(session.id) } catch (e) { errorMessage.value = e.message } finally { reportLoading.value = false } }
async function loadSessions(openFirst = true) { refreshing.value = true; errorMessage.value = ''; try { sessions.value = await getSessions(); if (page.value > pageCount.value) page.value = pageCount.value; const current = selected.value && visibleSessions.value.find(item => item.id === selected.value.id); const target = current || (openFirst ? pageSessions.value[0] : null); if (target) await openReport(target) } catch (e) { errorMessage.value = e.message } finally { refreshing.value = false } }
async function switchMode(nextMode) { mode.value = nextMode; page.value = 1; report.value = null; selected.value = null; await loadSessions() }
async function archiveSelected(session) { if (!window.confirm('确定要归档这项统计吗？归档后会从默认列表隐藏。')) return; archiving.value = true; try { await archiveSession(session.id); sessions.value = sessions.value.filter(item => item.id !== session.id); report.value = null; selected.value = null; if (page.value > pageCount.value) page.value = pageCount.value; if (pageSessions.value[0]) await openReport(pageSessions.value[0]) } catch (e) { errorMessage.value = e.message } finally { archiving.value = false } }
async function changePage(nextPage) { page.value = Math.min(pageCount.value, Math.max(1, nextPage)); if (pageSessions.value[0]) await openReport(pageSessions.value[0]) }
onMounted(async () => { try { await loadSessions() } finally { loading.value = false } })
</script>

<template>
  <main class="app-shell"><header class="topbar"><div><RouterLink class="back-link-inline" to="/teacher">← 返回老师工作台</RouterLink><p class="eyebrow">REPORTS</p><h1>习题统计</h1><p class="muted">查看即时课堂和课后练习的班级整体作答分布。</p></div></header>
    <p v-if="loading" class="loading-state">正在读取统计列表…</p><p v-else-if="errorMessage && !reportLoading" class="error-message">{{ errorMessage }}</p>
    <section v-else class="reports-layout"><div class="report-tabs"><button class="choice-card" :class="{ active: mode === 'classroom' }" @click="switchMode('classroom')">即时统计</button><button class="choice-card" :class="{ active: mode === 'homework' }" @click="switchMode('homework')">课后统计</button><button class="secondary-button report-refresh-button" :disabled="refreshing" @click="loadSessions(false)">{{ refreshing ? '读取中…' : '重新整理' }}</button></div>
      <div class="reports-layout-inner"><aside class="report-sessions"><h2>{{ mode === 'classroom' ? '已结束课堂' : '课后练习' }}</h2><button v-for="item in pageSessions" :key="item.id" :class="{ active: selected?.id === item.id }" class="choice-row" @click="openReport(item)"><span>{{ item.question_sets?.name || '题目集合' }}<small>{{ item.classes?.name || item.classes?.code || '' }}</small><small>{{ sessionTime(item) }}</small></span></button><p v-if="!visibleSessions.length" class="empty-state">目前还没有可查看的{{ mode === 'classroom' ? '已结束课堂' : '课后练习' }}。</p><div v-else class="pagination"><button class="secondary-button" :disabled="page <= 1" @click="changePage(page - 1)">上一页</button><span>第 {{ page }} / {{ pageCount }} 页</span><button class="secondary-button" :disabled="page >= pageCount" @click="changePage(page + 1)">下一页</button></div></aside>
        <section class="report-panel"><p v-if="reportLoading" class="loading-state">正在读取统计…</p><template v-else-if="report"><div class="report-context"><strong>{{ report.session.question_sets?.name || '题目集合' }}</strong><span>{{ report.session.classes?.name || report.session.classes?.code || '' }}</span><span>{{ isHomework ? `建立时间：${formatDate(report.session.created_at)}` : `结束时间：${formatDate(report.session.closed_at)}` }}</span><button class="secondary-button archive-button" :disabled="archiving" @click="archiveSelected(selected)">{{ archiving ? '归档中…' : '归档' }}</button></div><div class="report-summary"><span>{{ isHomework ? '最近一次完成设备' : '已加入设备' }} <strong>{{ report.participant_count }}</strong> 台</span><span>{{ isHomework ? '完成轮次' : '总提交' }} <strong>{{ isHomework ? report.completed_attempt_count : report.total_submitted_count }}</strong> 次</span></div><article v-for="question in report.questions" :key="question.id" class="report-question"><div class="report-question-heading"><div><span class="question-number">{{ question.sort_order }}</span><strong>{{ question.question_text || '图片题目' }}</strong><img v-if="question.question_image_url" :src="question.question_image_url" class="question-image report-question-image" alt="題目圖片" /></div><span :class="accuracyClass(question.accuracy)">正确率 {{ question.accuracy }}%</span></div><p class="correct-answer">正确答案：<strong>{{ question.correct_option_key || '未设置' }}</strong></p><div class="report-bars"><div v-for="key in ['A','B','C','D']" :key="key" class="report-bar"><span>{{ key }}</span><div><i :style="{ width: `${question.submitted_count ? question.distribution[key] / question.submitted_count * 100 : 0}%` }"></i></div><b>{{ question.distribution[key] }}</b></div></div><p class="helper-text">已作答 {{ question.submitted_count }} 人，答对 {{ question.correct_count }} 人</p></article></template><p v-else class="empty-state">请选择一项统计。</p></section></div></section>
  </main>
</template>
